export type RelatedUnit = {
  /**
   * The case-insensitive unique name of this related unit, unique across all related units. **NOTE**: Related units do not have a `fullName` field because they are not hierarchical objects, which is why `name` is unique for them but not for objects that have parents. Maximum length: 31 characters.
   */
  name: string;
  /**
   * The related unit's short identifier shown in the QuickBooks U/M field on transaction line items. Maximum length: 31 characters.
   */
  abbreviation: string;
  /**
   * The number of base units in this related unit, represented as a decimal string. For example, if the base unit is "box" and this related unit is "case" with `conversionRatio` = "10", that means there are 10 boxes in one case.
   */
  conversionRatio?: number;
};

/**
 * Defines a related unit of measure with its conversion ratio to the base unit.
 * Maps to the repeating QBXML RelatedUnit element.
 *
 * QBXML Schema Constraints:
 * - Name: Required, max length = 31
 * - Abbreviation: Required, max length = 31
 * - ConversionRatio: Required, PRICETYPE (min = 0.001, max = 5000)
 */
export type RelatedUnitRequest = {
  /**
   * (Required) The name of the related unit (e.g., "Gallon"). Max length: 31.
   */
  name: string;
  /**
   * (Required) The abbreviation of the related unit (e.g., "gal"). Max length: 31.
   */
  abbreviation: string;
  /**
   * (Required) The conversion ratio to the BaseUnit (e.g., 42 for Barrel to Gallons).
   * Valid range: 0.001 to 5000.
   */
  conversionRatio: number;
};

/**
 * Generic QuickBooks Report object (e.g., Aging, Custom).
 * A report is a method for obtaining a comprehensive view of data across multiple objects and over a specified time period, as opposed to a query, which typically just provides a simple snapshot of specific objects.
 * Reports are capable of spanning multiple data types and can be customized in a wide variety of ways.
 * When QuickBooks returns a report response, it generally contains two main types of information:
 * Report Meta-data: This information describes the report as a whole.
 * It includes the report's title and subtitle, the report basis (such as Cash, Accrual, or None), the total number of rows and columns, the number of rows used for column titles, and a column descriptor for each column that outlines its ID, title, column type, and data type.
 * Report Data: This is the actual content, presented as sequential rows of data expressed in name/value pairs.
 * These rows are further categorized into four types: text rows (mainly used for headings), data rows(the core report data), subtotal rows(calculated subtotals), and a single total row(the calculated total for the entire report).
 */
export type Report = {
  /**
   * The unique nexus identifier for the report object in the REST API.
   */
  id?: string | null;
  objectType?: string;
  createdAt: string;
  updatedAt: string;
  revisionNumber: string;
  title?: string | null;
  subtitle?: string | null;
  basis?: string | null;
  period?: string | null;
  rowCount?: number | null;
  columnCount?: number | null;
  headerRowCount?: number | null;
  columns?: Array<ReportColumnDescription> | null;
  data?: ReportData | null;
  customFields?: Array<QbdDataExt>;
};

/**
 * Represents a single column's data within a row (maps ColData QBXML element).
 */
export type ReportColData = {
  columnId?: string | null;
  /**
   * The value of the column.
   */
  value?: string | null;
  /**
   * The data type of the column.
   */
  dataType?: string | null;
  /**
   * The attributes of the column.
   */
  attributes?: DictionaryStringString | null;
};

/**
 * Describes a column in the report (maps ColDesc QBXML element).
 */
export type ReportColumnDescription = {
  id: string;
  /**
   * The data type of the column.
   */
  dataType?: string | null;
  type?: string | null;
  /**
   * The column titles for the report.
   */
  columnTitles?: Array<ReportColumnTitle> | null;
};

/**
 * Represents a column title (maps ColTitle QBXML element).
 * Supports hierarchical/nested column headers.
 */
export type ReportColumnTitle = {
  /**
   * The title row of the column.
   */
  titleRow?: number | null;
  /**
   * The value of the column title.
   */
  value?: string | null;
  /**
   * The sub-titles for the column.
   */
  subTitles?: Array<ReportColumnTitle> | null;
};

/**
 * Container for the report's data content (maps ReportData QBXML element).
 */
export type ReportData = {
  /**
   * The rows in the report.
   */
  rows?: Array<ReportRow> | null;
};

/**
 * Represents a single row in the report (Unified for Text, Data, Subtotal, and Total).
 */
export type ReportRow = {
  /**
   * The type of the row.
   */
  type?: string;
  /**
   * The row number of the row.
   */
  rowNumber?: number | null;
  /**
   * The value of the row.
   */
  value?: string | null;
  info?: ReportRowData | null;
  values?: Array<ReportColData> | null;
  rows?: Array<ReportRow> | null;
};

/**
 * Container for row metadata (maps RowData QBXML element within a DataRow).
 */
export type ReportRowData = {
  type?: string | null;
  /**
   * The value of the row.
   */
  value?: string | null;
  /**
   * The row number of the row.
   */
  rowNumber?: number | null;
};

/**
 * Response after rotating the publishable key
 */
export type RotatePublishableKeyResponse = {
  /**
   * The new publishable key — update all auth flow URLs with this.
   */
  publishableKey?: string;
  message?: string;
  rotatedAt?: string;
};

